graphql.query:
query TrendingAnime($page: Int!, $perPage: Int!) {
  Page(page: $page, perPage: $perPage) {
    pageInfo { currentPage hasNextPage lastPage total }
    media(type: ANIME, isAdult: false, sort: [TRENDING_DESC, POPULARITY_DESC]) {
      id
      title { romaji english native }
      coverImage { large extraLarge }
      bannerImage format status episodes countryOfOrigin season seasonYear averageScore popularity
    }
  }
}

query PopularAnime($page: Int!, $perPage: Int!) {
  Page(page: $page, perPage: $perPage) {
    pageInfo { currentPage hasNextPage lastPage total }
    media(type: ANIME, isAdult: false, sort: [POPULARITY_DESC, SCORE_DESC]) {
      id
      title { romaji english native }
      coverImage { large extraLarge }
      bannerImage format status episodes countryOfOrigin season seasonYear averageScore popularity
    }
  }
}

query NewEpisodesAnime($page: Int!, $perPage: Int!) {
  Page(page: $page, perPage: $perPage) {
    pageInfo { currentPage hasNextPage lastPage total }
    airingSchedules(notYetAired: false, sort: [TIME_DESC]) {
      episode airingAt
      media {
        id
        title { romaji english native }
        coverImage { large extraLarge }
        bannerImage format status episodes countryOfOrigin season seasonYear averageScore popularity
        endDate { year month day }
      }
    }
  }
}

query RecentlyCompletedAnime($page: Int!, $perPage: Int!) {
  Page(page: $page, perPage: $perPage) {
    pageInfo { currentPage hasNextPage lastPage total }
    media(type: ANIME, isAdult: false, status: FINISHED, sort: [END_DATE_DESC, POPULARITY_DESC]) {
      id
      title { romaji english native }
      coverImage { large extraLarge }
      bannerImage format status episodes countryOfOrigin season seasonYear averageScore popularity
      endDate { year month day }
    }
  }
}

query SearchAnime($search: String!, $page: Int!, $perPage: Int!, $sort: [MediaSort]) {
  Page(page: $page, perPage: $perPage) {
    pageInfo { currentPage hasNextPage lastPage total }
    media(type: ANIME, isAdult: false, search: $search, sort: $sort) {
      id
      title { romaji english native }
      coverImage { large extraLarge }
      bannerImage format status episodes countryOfOrigin season seasonYear averageScore popularity
    }
  }
}

query AnimeDetail($id: Int!) {
  Media(id: $id, type: ANIME) {
    id
    title { romaji english native }
    coverImage { large extraLarge }
    bannerImage format status episodes countryOfOrigin season seasonYear averageScore popularity
    description(asHtml: false)
    genres
    siteUrl
  }
}
